 for(let d=0;d<7;d++){const ws_=[];for(const p of(v['d'+d]||'').split(',').map(x=>x.trim()).filter(Boolean)){const m=/^(\d{1,2}:\d{2})-(\d{1,2}:\d{2})$/.exec(p),a=m&&pm(m[1]),b=m&&pm(m[2]);if(!m||a==null||b==null||b<=a||b>1440)return er.textContent=`${DOW[d]}: formato inválido “${p}”.`;ws_.push({start:a,end:b})}ws_.sort((x,y)=>x.start-y.start);if(ws_.some((w,i)=>i&&ws_[i-1].end>w.start))return er.textContent=`${DOW[d]}: ventanas solapadas.`;av[d]=ws_}
